"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1137-01-01:0":{"b": ["Fâtik II dibunuh; Fâtik III b. Muhammad menjadi penguasa dan Sürûr menjadi wazir (531).", "2f2d69ac"], "d": ["Fâtik II dibunuh; Fâtik III b. Muhammad menjadi penguasa dan Sürûr menjadi wazir (531).", "2f2d69ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:0":{"b": ["Setelah kemenangan Katvân, Khwarazmshah menerima tunduk kepada Kara Khitai dan membayar upeti", "5719a5ee"], "d": ["Setelah Kara Khitai mengalahkan Sencer di Katvân dan menguasai seluruh Transoxiana, pada tahun yang sama Khwarazmshah juga menjadi vasal Kara Khitai dan menerima membayar upeti (30.000 dinar per tahun). Ketundukan ini berlangsung hingga 1173, ketika Tekiş naik takhta Khwarazm dengan dukungan Kara Khitai.", "ab6f992b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:1":{"b": ["Kakuyiyah terakhir tewas dalam pertempuran Katvân; di Yazd tempat mereka diambil alih oleh Atabeg Yazd", "272bdc16"], "d": ["Kakuyiyah terakhir tewas dalam pertempuran Katvân; di Yazd tempat mereka diambil alih oleh Atabeg Yazd", "272bdc16"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1142-02-01:0":{"b": ["Gurkhan Yeh-lü Ta-şi meninggal; istrinya Kuyang (Tu-pu-yen) menggantikannya", "29e8156e"], "d": ["Penguasa Kara Khitai pertama Gurkhan Yeh-lü Ta-şi (1130-1142) meninggal pada bulan Februari 1142 (atau 1143); ia digantikan berturut-turut oleh istrinya Tu-pu-yen (Kuyang), putranya Yeh-lü Yi-lie, saudara perempuannya Yeh-lü-şe atau wakilnya Pu-su-wan. Dengan kemenangan Katvân (1141), seluruh Transoxiana dan Khwarazm telah dikenai pajak.", "5412642d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1150-01-01:0":{"b": ["Ümmü Fâtik Alem meninggal; Sürûr mengumpulkan seluruh kekuasaan di tangannya (545).", "5a5e3fcd"], "d": ["Ümmü Fâtik Alem meninggal; Sürûr mengumpulkan seluruh kekuasaan di tangannya (545).", "5a5e3fcd"]},
